_NONCE_SIZE = 12

_K_PARTS = [11, 98, 38, 94, 47, 163, 64, 236, 251, 181, 181, 55, 83, 210, 59, 55, 97, 176, 70, 182, 128, 123, 220, 43, 243, 48, 63, 24, 183, 111, 112, 146]
_K_MASK = [126, 58, 20, 18, 94, 197, 49, 240, 125, 20, 138, 184, 138, 228, 121, 192, 137, 55, 210, 105, 62, 111, 144, 145, 242, 178, 177, 190, 78, 47, 37, 113]

def _rebuild_key():
    parts = _K_PARTS
    mask = _K_MASK
    key = bytes(p ^ m for p, m in zip(parts, mask))
    return key

def _run():
    raw = base64.b85decode(_PAYLOAD)
    nonce, ciphertext = raw[:_NONCE_SIZE], raw[_NONCE_SIZE:]
    key = _rebuild_key()
    aesgcm = AESGCM(key)
    try:
        compressed = aesgcm.decrypt(nonce, ciphertext, None)
    except Exception:
        sys.stderr.write("Corrupted or tampered protected file.\n")
        sys.exit(1)
    raw_bytecode = zlib.decompress(compressed)
    code_obj = marshal.loads(raw_bytecode)
    exec(code_obj, {"__name__": "__main__"})

_run()
